def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    char_index = {char: i for i, char in enumerate(alphabet)}
    width = len(alphabet)
    transitions = [[-1] * width]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            index = char_index[char]
            if transitions[state][index] == -1:
                transitions[state][index] = len(transitions)
                transitions.append([-1] * width)
                terminal.append(False)
            state = transitions[state][index]
        terminal[state] = True

    from collections import deque

    failure = [0] * len(transitions)
    queue = deque()

    for index in range(width):
        child = transitions[0][index]
        if child == -1:
            transitions[0][index] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for index in range(width):
            child = transitions[state][index]
            if child == -1:
                transitions[state][index] = transitions[failure[state]][index]
            else:
                failure[child] = transitions[failure[state]][index]
                queue.append(child)

    safe_states = [state for state in range(len(transitions)) if not terminal[state]]
    state_index = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for state in safe_states:
        row = matrix[state_index[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[state_index[target]] += 1

    def multiply_matrices(left, right):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            result_row = result[i]
            for k, value in enumerate(left[i]):
                if value:
                    right_row = right[k]
                    for j in range(size):
                        result_row[j] += value * right_row[j]
            for j in range(size):
                result_row[j] %= MOD
        return result

    def multiply_vector(vector, matrix):
        result = [0] * size
        for i, value in enumerate(vector):
            if value:
                row = matrix[i]
                for j in range(size):
                    result[j] += value * row[j]
        return [value % MOD for value in result]

    vector = [0] * size
    vector[state_index[0]] = 1

    while n:
        if n & 1:
            vector = multiply_vector(vector, matrix)
        n >>= 1
        if n:
            matrix = multiply_matrices(matrix, matrix)

    return sum(vector) % MOD
